package tetris;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.prefs.Preferences;

/** Minimal, resizable Swing edition. */
public final class Main {
    private static final Preferences PREFS=Preferences.userNodeForPackage(Main.class);
    private static final Color[] COLORS={new Color(93,163,177),new Color(205,165,91),new Color(150,124,178),new Color(105,165,125),new Color(202,112,112),new Color(105,130,179),new Color(209,142,88)};
    private static final String[] TYPES=GameEngine.TYPES;
    private final GameEngine game=new GameEngine(); private final BoardView view=new BoardView(); private boolean muted=true;
    private Main(){game.highScore=PREFS.getInt("highScore",0);JFrame frame=new JFrame("Tetris — Stillwater");frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);frame.setMinimumSize(new Dimension(800,620));frame.setSize(1080,780);frame.setLocationRelativeTo(null);frame.setContentPane(view);frame.setVisible(true);view.setFocusable(true);view.requestFocusInWindow();long[] lastFrame={System.nanoTime()};new Timer(16,e->{long now=System.nanoTime();double elapsed=(now-lastFrame[0])/1_000_000_000.0;lastFrame[0]=now;game.update(elapsed);if(game.highScore>PREFS.getInt("highScore",0))PREFS.putInt("highScore",game.highScore);view.repaint();}).start();}
    private int colorIndex(String type){for(int i=0;i<TYPES.length;i++)if(TYPES[i].equals(type))return i;return 0;}
    private final class BoardView extends JPanel {
        BoardView(){setBackground(new Color(237,241,240));setFocusable(true);addKeyListener(new KeyAdapter(){@Override public void keyPressed(KeyEvent e){handle(e);}});addMouseListener(new MouseAdapter(){@Override public void mouseClicked(MouseEvent e){if(game.state==GameEngine.State.MENU){int middle=getHeight()/2+18;if(e.getY()<middle+44){game.start();}else if(e.getY()<middle+68){game.state=GameEngine.State.CONTROLS;}else System.exit(0);requestFocusInWindow();}else if(game.state==GameEngine.State.GAME_OVER||game.state==GameEngine.State.PAUSED){if(e.getY()>getHeight()/2){game.start();}else game.state=GameEngine.State.MENU;}}});}
        private void handle(KeyEvent e){int k=e.getKeyCode();if(k==KeyEvent.VK_M){muted=!muted;repaint();return;}if(game.state==GameEngine.State.MENU||game.state==GameEngine.State.CONTROLS){if(game.state==GameEngine.State.MENU&&k==KeyEvent.VK_Q)System.exit(0);if(k==KeyEvent.VK_ENTER){if(game.state==GameEngine.State.CONTROLS)game.state=GameEngine.State.MENU;else game.start();}else if(k==KeyEvent.VK_C||k==KeyEvent.VK_ESCAPE)game.state=game.state==GameEngine.State.CONTROLS?GameEngine.State.MENU:GameEngine.State.CONTROLS;repaint();return;}if(game.state==GameEngine.State.PAUSED){if(k==KeyEvent.VK_ENTER)game.togglePause();else if(k==KeyEvent.VK_R)game.start();else if(k==KeyEvent.VK_Q)game.state=GameEngine.State.MENU;}else if(game.state==GameEngine.State.GAME_OVER){if(k==KeyEvent.VK_ENTER)game.start();else if(k==KeyEvent.VK_Q)game.state=GameEngine.State.MENU;}else if(k==KeyEvent.VK_ESCAPE||k==KeyEvent.VK_P){game.togglePause();}else if(k==KeyEvent.VK_R)game.start();else if(game.state==GameEngine.State.PLAYING){switch(k){case KeyEvent.VK_LEFT,KeyEvent.VK_A->game.move(-1,0);case KeyEvent.VK_RIGHT,KeyEvent.VK_D->game.move(1,0);case KeyEvent.VK_DOWN,KeyEvent.VK_S->game.softDrop();case KeyEvent.VK_UP,KeyEvent.VK_X->{game.rotate(1);if(!muted)Audio.tone(540);}case KeyEvent.VK_Z->{game.rotate(-1);if(!muted)Audio.tone(420);}case KeyEvent.VK_SPACE->{game.hardDrop();if(!muted)Audio.tone(250);}case KeyEvent.VK_C,KeyEvent.VK_SHIFT->{game.hold();if(!muted)Audio.tone(340);}default->{}}}repaint();}
        private void label(Graphics2D g,String s,int x,int y,int size,Color c,boolean bold){g.setFont(new Font("SansSerif",bold?Font.BOLD:Font.PLAIN,size));g.setColor(c);g.drawString(s,x,y);}
        private void cell(Graphics2D g,int x,int y,int size,String kind,boolean ghost){int idx=colorIndex(kind);if(ghost){g.setColor(new Color(128,147,143,85));g.setStroke(new BasicStroke(1.5f));g.drawRoundRect(x+3,y+3,size-6,size-6,6,6);return;}g.setColor(COLORS[idx]);g.fillRoundRect(x+1,y+1,size-2,size-2,Math.max(4,size/5),Math.max(4,size/5));g.setColor(new Color(255,255,255,75));g.fillRoundRect(x+size/5,y+size/7,size*3/5,Math.max(2,size/18),3,3);}
        private void mini(Graphics2D g,String kind,int x,int y,int unit){if(kind==null)return;for(int[] c:GameEngine.cells(kind,0))cell(g,x+c[0]*unit,y+c[1]*unit,unit,kind,false);}
        @Override protected void paintComponent(Graphics raw){super.paintComponent(raw);Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int w=getWidth(),h=getHeight();g.setColor(new Color(237,241,240));g.fillRect(0,0,w,h);label(g,"T E T R I S",36,39,15,new Color(47,60,62),true);label(g,"S T I L L W A T E R     SOUND "+(muted?"OFF":"ON"),w-250,38,10,new Color(130,145,143),true);
            int cell=Math.max(17,Math.min(34,Math.min((h-105)/20,(w-320)/14)));int bw=cell*10,bh=cell*20,bx=(w-bw)/2,by=(h-bh)/2+18;g.setColor(new Color(255,255,255));g.fillRoundRect(bx-9,by-9,bw+18,bh+18,14,14);g.setColor(new Color(217,225,222));g.drawRoundRect(bx-9,by-9,bw+18,bh+18,14,14);
            for(int y=0;y<GameEngine.HEIGHT;y++)for(int x=0;x<GameEngine.WIDTH;x++){int px=bx+x*cell,py=by+y*cell;g.setColor(new Color(244,247,245));g.fillRect(px+1,py+1,cell-2,cell-2);if(game.board[y][x]!=null)cell(g,px,py,cell,game.board[y][x],false);}
            if(game.state==GameEngine.State.PLAYING){GameEngine.Piece ghost=game.ghost();for(int[] c:game.cells(ghost))if(c[1]>=0)cell(g,bx+c[0]*cell,by+c[1]*cell,cell,ghost.kind,true);for(int[] c:game.cells(game.active))if(c[1]>=0)cell(g,bx+c[0]*cell,by+c[1]*cell,cell,game.active.kind,false);}
            int lx=bx-111,rx=bx+bw+34;label(g,"HOLD",lx,by+6,10,new Color(127,143,139),true);g.setColor(new Color(255,255,255,180));g.fillRoundRect(lx-8,by+18,86,66,9,9);mini(g,game.held,lx+6,by+31,12);
            label(g,"UP NEXT",rx,by+6,10,new Color(127,143,139),true);for(int i=0;i<3;i++){g.setColor(new Color(255,255,255,180));g.fillRoundRect(rx-9,by+18+i*62,89,53,9,9);mini(g,game.queue.get(i),rx+5,by+26+i*62,11);}
            label(g,"SCORE",rx,by+240,10,new Color(127,143,139),true);label(g,String.format("%06d",game.score),rx,by+266,19,new Color(47,60,62),true);label(g,"BEST",rx,by+306,10,new Color(127,143,139),true);label(g,String.format("%06d",game.highScore),rx,by+329,15,new Color(83,101,98),false);label(g,"LEVEL   "+game.level,rx,by+372,11,new Color(83,101,98),true);label(g,"LINES   "+game.lines,rx,by+401,11,new Color(83,101,98),true);
            label(g,"← / A MOVE     → / D MOVE     ↓ / S SOFT DROP     SPACE HARD DROP     X / ↑ TURN     Z REVERSE     C HOLD",Math.max(18,(w-720)/2),h-19,9,new Color(130,145,143),true);
            if(game.state!=GameEngine.State.PLAYING){g.setColor(new Color(237,241,240,225));g.fillRect(bx,by,bw,bh);String title;String[] lines;if(game.state==GameEngine.State.MENU){title="TETRIS";lines=new String[]{"A little room to think","ENTER   PLAY","C   CONTROLS","Q   QUIT"};}else if(game.state==GameEngine.State.CONTROLS){title="CONTROLS";lines=new String[]{"ARROWS / A D   MOVE","DOWN / S   SOFT DROP     SPACE   HARD DROP","UP / X   TURN     Z   REVERSE","C / SHIFT   HOLD     P / ESC   PAUSE","M   SOUND     ENTER   BACK"};}else if(game.state==GameEngine.State.PAUSED){title="PAUSED";lines=new String[]{"ENTER   RESUME","R   RESTART","Q   MAIN MENU"};}else{title="GAME OVER";lines=new String[]{"FINAL SCORE   "+game.score,"BEST SCORE   "+game.highScore,"ENTER   RESTART","Q   MAIN MENU"};}FontMetrics fm=g.getFontMetrics();label(g,title,bx+bw/2-fm.stringWidth(title)/2,by+bh/2-34,26,new Color(47,60,62),true);for(int i=0;i<lines.length;i++){Font f=new Font("SansSerif",i==0?Font.BOLD:Font.PLAIN,12);g.setFont(f);FontMetrics m=g.getFontMetrics();g.setColor(i==0?new Color(73,139,122):new Color(103,119,115));g.drawString(lines[i],bx+bw/2-m.stringWidth(lines[i])/2,by+bh/2+8+i*24);}}
            g.dispose();}
    }
    public static void main(String[] args){SwingUtilities.invokeLater(Main::new);}
}
